fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let band: i32 = h / 3;
    host::display::fill_rect(0, 0, w, band, 0xff0000);
    host::display::fill_rect(0, band, w, band, 0x00ff00);
    host::display::fill_rect(0, band * 2, w, h - band * 2, 0x0000ff);
    host::display::present();
}
